import { Group, Mesh, PlaneGeometry, Vector3, Color } from 'three/webgpu';
import {
    tslStandardMaterial,
    TextureNode,
    FloatNode,
    ColorNode,
    OperatorNode,
    AddNode,
    SubNode,
    MultiplyNode,
    UVNode,
    TransformNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createMsdfMesh } from '@/text';

export default function createNode(config, ctx) {
    const root = new Group();
    root.position.set(0, 0, 0);
    root.scale.set(1, 1, 1);
    root.rotation.set(0, 0, 0);
    root.userData.handlers = {};
    const cleanupTasks = [];

    // ---------- TEXTURES ----------
    const baseTexture = ctx.textureLoader('/prism-mock/home/nodes/feature-card.png');

    // ---------- PLATE SETTINGS ----------
    const PLATE_COUNT = 6;
    const PLATE_WIDTH = 1.9;
    const PLATE_HEIGHT = 1.2;
    const PLATE_PITCH = 1.5; // vertical distance between plates
    const COLUMN_X = 0.9; // column offset
    const LOOP_LENGTH = PLATE_COUNT * PLATE_PITCH; // 9.0 units
    const BEVEL_THICK = 0.03;
    const ACCENT_STRIP_W = 0.03;
    const ACCENT_COLOR = new Color('#ff2a38');

    // ---------- MATERIALS ----------
    const plateMaterial = tslStandardMaterial({
        map: new TextureNode(baseTexture),
        roughness: new FloatNode(0.6),
        metalness: new FloatNode(0.1),
        clearcoat: new FloatNode(0.1),
    });

    const bevelMaterial = tslStandardMaterial({
        color: new ColorNode(new Color('#16161d')),
        roughness: new FloatNode(0.5),
        metalness: new FloatNode(0.5),
    });

    const accentMaterial = tslStandardMaterial({
        color: new ColorNode(ACCENT_COLOR),
        emissive: new ColorNode(ACCENT_COLOR),
        emissiveIntensity: new FloatNode(1.4),
        metalness: new FloatNode(0.0),
        roughness: new FloatNode(0.0),
    });

    // ---------- PLATES ----------
    const plates = [];
    const captions = [
        'DIAL ROOM',
        'ESCAPEMENT BENCH',
        'CNC HALL',
        'FINISHING LAB',
        'ARCHIVE VAULT',
        'ASSEMBLY LINE ONE',
    ];

    for (let i = 0; i < PLATE_COUNT; i++) {
        const plateGroup = new Group();
        plateGroup.position.set(COLUMN_X, i * PLATE_PITCH, 0);
        // ------- main plane -------
        const planeGeo = new PlaneGeometry(PLATE_WIDTH, PLATE_HEIGHT);
        // Apply a unique UV transform per plate to simulate distinct crops
        const uvTransform = new TransformNode();
        uvTransform.setScale(new Vector3(0.9, 0.9, 1));
        uvTransform.setOffset(new Vector3(0.05 * i, 0.05 * i, 0));
        const uvNode = new UVNode();
        const shiftedUV = new OperatorNode(uvNode, uvTransform, OperatorNode.MUL);
        // Override map node uv with shiftedUV
        plateMaterial.map = new TextureNode(baseTexture, shiftedUV);
        const plateMesh = new Mesh(planeGeo, plateMaterial);
        plateGroup.add(plateMesh);

        // ------- bevel frame -------
        const bevelGeo = new PlaneGeometry(PLATE_WIDTH + BEVEL_THICK * 2, PLATE_HEIGHT + BEVEL_THICK * 2);
        const bevelMesh = new Mesh(bevelGeo, bevelMaterial);
        bevelMesh.position.set(0, 0, -0.001); // slightly behind
        plateGroup.add(bevelMesh);

        // ------- accent strip -------
        const stripGeo = new PlaneGeometry(ACCENT_STRIP_W, PLATE_HEIGHT);
        const stripMesh = new Mesh(stripGeo, accentMaterial);
        stripMesh.position.set(-PLATE_WIDTH / 2 - ACCENT_STRIP_W / 2, 0, 0.001);
        plateGroup.add(stripMesh);

        // ------- caption (MSDF) -------
        const captionText = captions[i];
        const captionMesh = createMsdfMesh(captionText, {
            fontSize: 18,
            fontWeight: 400,
            family: 'JetBrains Mono',
            color: '#e8ecf2',
            letterSpacing: 0.08,
            lineHeight: 1.4,
            // region from atlas as requested
            region: { atlas: 0, x: 0, y: 0, w: 512, h: 320 },
        }, ctx.fontAtlas);
        // Position caption left of plate
        captionMesh.position.set(-PLATE_WIDTH / 2 - 0.1, -0.4, 0.002);
        captionMesh.scale.set(0.6, 0.6, 0.6);
        captionMesh.visible = false; // start hidden
        plateGroup.add(captionMesh);

        // store references
        plates.push({
            group: plateGroup,
            mesh: plateMesh,
            caption: captionMesh,
            scaleTween: null,
            captionTween: null,
        });

        root.add(plateGroup);
    }

    // ---------- HEADLINE ----------
    const headlineMesh = createMsdfMesh('Inside the atelier', {
        fontSize: 68,
        fontWeight: 600,
        family: 'Lora',
        color: '#e8ecf2',
        letterSpacing: -0.005,
        lineHeight: 1.1,
        region: { atlas: 0, x: 0, y: 0, w: 512, h: 320 },
    }, ctx.fontAtlas);
    headlineMesh.position.set(-1.6, 1.9, 0);
    root.add(headlineMesh);

    // ---------- SCROLL HANDLER ----------
    const scrollState = { targetY: 0 };
    const inertiaTween = gsap.to(scrollState, {
        duration: 0.8,
        targetY: 0,
        ease: 'power3.out',
        onUpdate: applyScroll,
    });
    cleanupTasks.push(() => inertiaTween.kill());

    function setScroll(progress) {
        // progress expected 0..1
        const desiredY = -progress * LOOP_LENGTH;
        inertiaTween.kill();
        gsap.to(scrollState, {
            duration: 0.9,
            targetY: desiredY,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)',
            onUpdate: applyScroll,
        });
    }

    function applyScroll() {
        root.position.y = scrollState.targetY % LOOP_LENGTH;
        updateFocus();
    }

    function updateFocus() {
        // Determine plate whose world Y is nearest to 0
        let nearest = null;
        let minDist = Infinity;
        plates.forEach(p => {
            const worldY = root.position.y + p.group.position.y;
            const dist = Math.abs(worldY);
            if (dist < minDist) {
                minDist = dist;
                nearest = p;
            }
        });

        plates.forEach(p => {
            const isFocused = p === nearest;
            if (p.scaleTween) p.scaleTween.kill();
            if (p.captionTween) p.captionTween.kill();

            const targetScale = isFocused ? 1.06 : 1.0;
            const targetOpacity = isFocused ? 1.0 : 0.0;

            p.scaleTween = gsap.to(p.mesh.scale, {
                duration: 0.35,
                x: targetScale,
                y: targetScale,
                z: targetScale,
                ease: 'cubic-bezier(0.215,0.61,0.355,1)',
            });
            p.captionTween = gsap.to(p.caption.material, {
                duration: 0.35,
                opacity: targetOpacity,
                ease: 'cubic-bezier(0.215,0.61,0.355,1)',
                onStart: () => (p.caption.visible = true),
                onComplete: () => (p.caption.visible = targetOpacity > 0),
            });
        });
    }

    // ---------- PRIMITIVE ----------
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach(p => {
            if (ctx.primitives[p.name]) {
                ctx.primitives[p.name](root, p.params);
            }
        });
    }

    // ---------- HANDLERS ----------
    root.userData.handlers.scroll = setScroll;

    // ---------- CLEANUP ----------
    root.userData.cleanup = () => {
        cleanupTasks.forEach(fn => fn());
        plates.forEach(p => {
            p.mesh.geometry.dispose();
            p.caption.geometry.dispose();
        });
        plateMaterial.dispose();
        bevelMaterial.dispose();
        accentMaterial.dispose();
        baseTexture.dispose();
    };

    return root;
}
